-- chair-step: inverse of read_lane_v2_b2_19_chat_agent_task — un-enrolls chat.agent_task from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'chat' and table_name = 'agent_task' and is_active);
select iam.apply_rls('chat', 'agent_task', (select token from platform.entity_types where schema_name = 'chat' and table_name = 'agent_task' and is_active), (select rls_variant from platform.entity_types where schema_name = 'chat' and table_name = 'agent_task' and is_active));
